import type { SatForm, SatQuestion } from "./types";

/**
 * Practice Test 22 — a FULL-LENGTH adaptive digital-SAT form (original,
 * hand-verified items). Reading & Writing modules are 27 questions each;
 * Math modules are 22 questions each. Topics and passages are distinct from
 * earlier practice tests.
 */

// ─────────────────────── PRACTICE TEST 22 · R&W M1 (27) ──────────────────────
const T22_RW_M1: SatQuestion[] = [
  { id: "t22rw1-1", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The lecturer's explanation was so ______ that even students with no background in physics left the hall understanding the core idea.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["lucid", "convoluted", "tedious", "evasive"], correct: 0, explanation: "The answer is (A) lucid. The sentence says even students with no physics background left understanding the core idea, so the explanation must have been exceptionally clear; \"lucid\" means clear and easy to understand, which fits exactly. (B) convoluted means twisted and overly complex, the opposite of an explanation that everyone grasps. (C) tedious means boringly long; dullness would not cause understanding and does not address clarity. (D) evasive means deliberately vague or avoiding the point, which would prevent the listeners from understanding the idea." },
  { id: "t22rw1-2", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The committee of advisers ______ scheduled to meet with the mayor on Thursday afternoon.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "have been", "were"], correct: 0, explanation: "The answer is (A) is. The subject is the singular collective noun \"committee\"; the plural \"advisers\" is only the object of the preposition \"of\" and does not control the verb, so the singular \"is\" agrees. (B) are is plural and would agree only with a plural subject like \"advisers.\" (C) have been is plural present-perfect and disagrees with the singular \"committee.\" (D) were is plural past tense, wrong in both number and tense for the singular subject and present context." },
  { id: "t22rw1-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Tardigrades, microscopic animals less than a millimeter long, can survive boiling heat, near-absolute-zero cold, and the vacuum of space by entering a dried, dormant state called a tun.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Tardigrades endure extreme conditions by entering a dormant tun state.", "Tardigrades are the largest animals on Earth.", "Tardigrades cannot survive any temperature change.", "Tardigrades live only in the vacuum of space."], correct: 0, explanation: "The answer is (A). The text describes how tardigrades survive boiling heat, near-absolute-zero cold, and the vacuum of space by entering the dormant tun state, so the main idea is that this dormancy is what lets them endure extremes. (B) is wrong because the text calls them \"microscopic animals less than a millimeter long,\" the opposite of the largest animals on Earth. (C) is wrong because the text lists temperature extremes they do survive, contradicting the claim that they cannot survive any temperature change. (D) is wrong because surviving the vacuum of space is only one of several feats listed; nothing says they live only there." },
  { id: "t22rw1-4", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The harvest had been poor for two straight years. ______, the village rationed its grain through the winter.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nevertheless", "Consequently", "However", "In contrast"], correct: 1, explanation: "The answer is (B) Consequently. Two straight years of poor harvest is a cause, and rationing grain through the winter is its logical effect, so a result transition is needed. (A) Nevertheless signals contrast or concession, but there is no reversal here. (C) However also signals contrast, which the cause-and-effect relationship does not support. (D) In contrast sets up opposing ideas, but rationing follows naturally from the poor harvest rather than opposing it." },
  { id: "t22rw1-5", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The kit includes everything a beginner needs ______ a brush, a palette, and three tubes of paint.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["needs, ", "needs: ", "needs; ", "needs "], correct: 1, explanation: "The answer is (B) needs: . A colon correctly introduces the list (a brush, a palette, and three tubes of paint) that specifies \"everything a beginner needs.\" (A) needs, uses only a comma, which cannot formally introduce an explanatory list after a complete clause. (C) needs; uses a semicolon, which requires a full independent clause after it, but a list is not an independent clause. (D) needs leaves no punctuation, running the clause into the list." },
  { id: "t22rw1-6", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Unlike her flamboyant predecessor, the new director favored a ______ style, letting the music speak without theatrical gestures.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["restrained", "ostentatious", "chaotic", "frantic"], correct: 0, explanation: "The answer is (A) restrained. \"Unlike her flamboyant predecessor\" and \"without theatrical gestures\" signal a held-back style, which \"restrained\" means. (B) ostentatious is a synonym of flamboyant, the opposite of the needed contrast. (C) chaotic means disordered, which does not fit a director who lets the music speak quietly. (D) frantic means hurried and agitated, again the opposite of a controlled, gesture-free style." },
  { id: "t22rw1-7", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The fellowship is awarded only to writers who have published at least one full-length book and who are under the age of forty; unpublished or older applicants are not considered.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["A thirty-year-old who has never published a book cannot receive the fellowship.", "Anyone who applies receives the fellowship.", "Writers over forty are given preference.", "Only unpublished writers qualify."], correct: 0, explanation: "The answer is (A). The text states two requirements joined by \"and\": at least one full-length book AND being under forty; it adds that \"unpublished or older applicants are not considered.\" A thirty-year-old who has never published meets the age rule but fails the publication rule, so cannot receive the fellowship. (B) is wrong because the text restricts the award to qualifying applicants, not anyone who applies. (C) is wrong because the text says older applicants are excluded, so writers over forty are not preferred. (D) is wrong because publication is required, so it cannot be that only unpublished writers qualify." },
  { id: "t22rw1-8", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The trail was well marked and gently graded. ______, it offered sweeping views of the valley at every turn.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "Moreover", "Otherwise", "Instead"], correct: 1, explanation: "The answer is (B) Moreover. The first sentence praises the trail as well marked and gently graded, and the second adds a further positive feature (sweeping views), so an additive transition is needed. (A) However signals contrast, but the two sentences agree rather than oppose. (C) Otherwise sets up an alternative or consequence of not doing something, which does not fit. (D) Instead signals substitution of one thing for another, but the views are added to the trail's virtues, not substituted for them." },
  { id: "t22rw1-9", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Reviewers found the memoir ______, praising how candidly the author confronted his own mistakes.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["unflinching", "evasive", "superficial", "dishonest"], correct: 0, explanation: "The answer is (A) unflinching. Praising how candidly the author confronts his own mistakes describes work that refuses to look away, which \"unflinching\" means. (B) evasive means avoiding the point, the opposite of confronting mistakes candidly. (C) superficial means shallow, contradicting the candid, searching self-examination described. (D) dishonest contradicts the praise for candor, since candor is honesty." },
  { id: "t22rw1-10", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Bees communicate the location of food through a 'waggle dance,' whose direction and duration encode the angle and distance to the flowers.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Bees use a dance to convey where food can be found.", "Bees cannot share information with one another.", "Bees dance only for entertainment.", "Bees find food entirely by chance."], correct: 0, explanation: "The answer is (A). The text says the waggle dance's direction and duration encode the angle and distance to the flowers, so the dance conveys where food can be found. (B) is wrong because the dance is itself a means of sharing information, contradicting the claim that bees cannot communicate. (C) is wrong because the dance serves a clear functional purpose (locating food), not entertainment. (D) is wrong because encoding the location of flowers is the opposite of finding food entirely by chance." },
  { id: "t22rw1-11", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "Neither the coach nor the players ______ satisfied with the referee's final call.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["was", "were", "is", "has been"], correct: 1, explanation: "The answer is (B) were. The proximity rule for \"neither…nor\" subjects says the verb agrees with the nearer subject, which here is the plural \"players,\" requiring the plural \"were.\" (A) was is singular and would agree only if the nearer noun were singular. (C) is is singular and present tense, doubly wrong for a plural past-context subject. (D) has been is singular present-perfect and does not agree with the plural \"players.\"" },
  { id: "t22rw1-12", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The first prototype overheated within minutes. ______, the engineers redesigned its cooling system before the second test.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Still", "For instance", "Therefore", "In short"], correct: 2, explanation: "The answer is (C) Therefore. The prototype overheated (cause), and the engineers redesigned the cooling system in response (effect), so a result transition fits. (A) Still signals contrast or concession, but the redesign follows from the problem rather than opposing it. (B) For instance would introduce an example, which the redesign is not. (D) In short signals a summary, but the second sentence presents a new consequence, not a recap." },
  { id: "t22rw1-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A clinic reported wait times of 45 minutes on Mondays, 30 minutes on Wednesdays, and 18 minutes on Fridays.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Wait times were shortest on Fridays.", "Wait times were longest on Fridays.", "Wednesday wait times exceeded Monday wait times.", "All three days had equal wait times."], correct: 0, explanation: "The answer is (A). The data give 45 minutes Monday, 30 minutes Wednesday, and 18 minutes Friday; 18 is the smallest, so Friday had the shortest wait. (B) is wrong because Friday's 18 minutes is the shortest, not the longest (Monday's 45 is longest). (C) is wrong because Wednesday's 30 is less than Monday's 45, so Wednesday did not exceed Monday. (D) is wrong because the three figures (45, 30, 18) differ, so the days were not equal." },
  { id: "t22rw1-14", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The novelist published a debut ______ would go on to win three major awards.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["that", "what", "where", "and it"], correct: 0, explanation: "The answer is (A) that. The relative pronoun \"that\" correctly introduces the clause \"would go on to win three major awards,\" which modifies the noun \"debut.\" (B) what cannot follow a noun antecedent; it introduces a noun clause, not a relative clause. (C) where marks a place, but \"debut\" is a thing, not a location. (D) and it joins the clauses without proper subordination, creating a run-on/comma-splice-style error." },
  { id: "t22rw1-15", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Sealing the envelope, ______ a sudden gust scattered the unsigned letters across the desk.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["sealing the envelope, a sudden gust scattered the letters", "the clerk had barely sealed the envelope when a gust scattered the letters", "the letters, sealing the envelope, scattered across the desk", "scattering, the gust sealed the envelope across the desk"], correct: 1, explanation: "The answer is (B). The introductory participial phrase \"Sealing the envelope\" must modify the noun that immediately follows it; only a person can seal an envelope, so the clerk must come next. Choice B recasts the sentence so \"the clerk\" performs the sealing, avoiding the dangling modifier. (A) is wrong because it makes \"a sudden gust\" the thing sealing the envelope, which is illogical. (C) is wrong because it makes \"the letters\" seal the envelope, equally illogical. (D) is wrong because it has \"the gust\" seal the envelope and garbles the meaning entirely." },
  { id: "t22rw1-16", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "A researcher claims that listening to instrumental music while studying improves recall because lyrics would otherwise compete for the brain's language resources.", prompt: "Which finding, if true, would most strengthen the researcher's claim?", type: "mcq", choices: ["Students who studied with lyric-free music recalled more than those who studied with lyrics.", "Most students prefer music with lyrics.", "Instrumental music is more expensive to produce.", "Studying in silence produced the same results as studying with lyrics."], correct: 0, explanation: "The answer is (A). The claim is that instrumental music aids recall because lyrics would compete for language resources; a result showing that students with lyric-free music recalled more than those with lyrics directly confirms that lyrics impair recall. (B) is wrong because student preference for lyrics says nothing about recall. (C) is wrong because the production cost of instrumental music is irrelevant to the memory mechanism. (D) is wrong because finding silence equal to lyrics does not isolate the effect of lyrics on language processing and does not support instrumental music's advantage." },
  { id: "t22rw1-17", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The director, together with her two producers, ______ unveiling the film at the festival next week.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "were", "have been"], correct: 0, explanation: "The answer is (A) is. The subject is the singular \"director\"; a phrase introduced by \"together with\" is parenthetical and does not change the verb's number, so the singular \"is\" agrees. (B) are is plural and would need a plural subject. (C) were is plural past tense, wrong in both number and the present \"next week\" context. (D) have been is plural present-perfect and disagrees with the singular \"director.\"" },
  { id: "t22rw1-18", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "A writer wants to emphasize that two independent labs reached identical conclusions. ______, both teams measured the reaction rate to within one percent of each other.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["By contrast", "Remarkably", "However", "Otherwise"], correct: 1, explanation: "The answer is (B) Remarkably. The writer wants to emphasize that two independent labs reached identical conclusions, and \"Remarkably\" stresses how striking that close agreement is. (A) By contrast signals opposition, but the labs agreed rather than differed. (C) However signals contrast, contradicting \"identical conclusions.\" (D) Otherwise introduces an alternative or consequence of not doing something, which does not fit two labs that agreed." },
  { id: "t22rw1-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The ending of the novel is intentionally ______: readers cannot tell whether the narrator's reconciliation with his brother is real or imagined.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["ambiguous", "explicit", "predictable", "cheerful"], correct: 0, explanation: "The answer is (A) ambiguous. Readers who cannot tell whether the reconciliation is real or imagined face an ending open to more than one reading, which \"ambiguous\" means. (B) explicit means clearly and fully stated, the opposite of the described uncertainty. (C) predictable means easily foreseen, but the ending leaves readers unsure. (D) cheerful describes a mood and does not address whether the ending is interpretable." },
  { id: "t22rw1-20", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The scholarship is open only to students who maintain a 3.5 grade average and who volunteer at least fifty hours per year in their community.", prompt: "Which student clearly qualifies for the scholarship?", type: "mcq", choices: ["A student with a 3.7 average who volunteers sixty hours a year.", "A student with a 3.2 average who volunteers eighty hours a year.", "A student with a 3.9 average who does no volunteering.", "A student with a 2.8 average who volunteers forty hours a year."], correct: 0, explanation: "The answer is (A). The scholarship requires both a 3.5+ average AND at least fifty volunteer hours; the 3.7-average student who volunteers sixty hours satisfies both. (B) is wrong because a 3.2 average falls below the 3.5 grade requirement despite the eighty hours. (C) is wrong because doing no volunteering fails the fifty-hour requirement despite the 3.9 average. (D) is wrong because a 2.8 average and only forty hours fail both conditions." },
  { id: "t22rw1-21", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The crew repaired the lighthouse ______ they repainted its weathered iron railing.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["lighthouse, and then", "lighthouse and, then", "lighthouse then", "lighthouse, then"], correct: 0, explanation: "The answer is (A). \"The crew repaired the lighthouse\" and \"they repainted its weathered iron railing\" are two independent clauses, which Standard English joins with a comma plus the coordinating conjunction \"and,\" giving \"lighthouse, and then.\" (B) is wrong because it places the comma after \"and,\" awkwardly splitting the conjunction from the clause it introduces. (C) is wrong because \"lighthouse then\" runs the two clauses together with no conjunction or punctuation. (D) is wrong because \"lighthouse, then\" joins two independent clauses with only a comma, creating a comma splice." },
  { id: "t22rw1-22", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Despite the magazine's reputation for ______ reviews, its critics occasionally lavished praise on an unknown filmmaker.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["scathing", "generous", "timid", "muted"], correct: 0, explanation: "The answer is (A) scathing. \"Despite the magazine's reputation for ___ reviews, its critics occasionally lavished praise\" sets up a contrast, so the usual reviews must be the opposite of praise—harsh, or \"scathing.\" (B) generous would not contrast with lavishing praise; it matches it. (C) timid means hesitant, which does not contrast meaningfully with praise. (D) muted means subdued, which likewise fails to oppose \"lavished praise.\"" },
  { id: "t22rw1-23", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "An economist observes that towns built along early railroads grew faster than those bypassed by the tracks, attributing the difference to cheaper access to distant markets.", prompt: "Which choice best describes the economist's explanation?", type: "mcq", choices: ["Railroad access lowered shipping costs, fueling faster growth.", "Bypassed towns enjoyed cheaper market access.", "Railroads slowed the growth of nearby towns.", "Town location had no effect on growth."], correct: 0, explanation: "The answer is (A). The economist says railroad towns grew faster and attributes the difference to cheaper access to distant markets, i.e., lower shipping costs fueled growth. (B) is wrong because it gives the cheaper access to bypassed towns, reversing who benefited. (C) is wrong because the railroad sped growth, not slowed it. (D) is wrong because the economist explicitly ties growth to location along the tracks, so location did matter." },
  { id: "t22rw1-24", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The council delayed the vote ______ several members had not yet reviewed the budget proposal.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["vote because", "vote, because", "vote; because", "vote: because"], correct: 0, explanation: "The answer is (A) vote because. When a dependent \"because\" clause follows the main clause, no punctuation is needed before \"because.\" (B) vote, because inserts an unneeded comma before a trailing dependent clause. (C) vote; because wrongly uses a semicolon, which must separate two independent clauses, but \"because…\" is dependent. (D) vote: because wrongly uses a colon, which should introduce a list or explanation set off as a complete idea, not a subordinate clause." },
  { id: "t22rw1-25", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The library digitized its entire archive of old newspapers. ______, researchers across the world can now search records that once required an in-person visit.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["As a result", "Nevertheless", "For example", "On the other hand"], correct: 0, explanation: "The answer is (A) As a result. Digitizing the archive is the cause, and worldwide searchability is its effect, so a result transition fits. (B) Nevertheless signals contrast or concession, but no reversal occurs. (C) For example would introduce an instance of a general claim, but the second sentence states a consequence, not an example. (D) On the other hand sets up an opposing point, which the cause-and-effect relationship does not support." },
  { id: "t22rw1-26", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The coach gave ______ feedback, pointing out exactly which drills each player should repeat the next day.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["specific", "vague", "irrelevant", "discouraging"], correct: 0, explanation: "The answer is (A) specific. The clause \"pointing out exactly which drills each player should repeat\" describes precise, detailed feedback, which is what \"specific\" means. (B) vague means unclear or imprecise, the opposite of pointing out exactly what to do. (C) irrelevant would mean the feedback was beside the point, but it directly guided practice. (D) discouraging describes a negative tone, but the sentence stresses precision, not negativity." },
  { id: "t22rw1-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "When sea otters were reintroduced to a kelp forest, they preyed on the sea urchins that had been devouring the kelp; freed from the urchins, the kelp rebounded, restoring habitat for fish and other species.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Restoring otters set off a chain of effects that revived the kelp forest.", "Otters directly planted the kelp.", "Sea urchin populations grew after the otters returned.", "The kelp declined once the otters arrived."], correct: 0, explanation: "The answer is (A). The otters preyed on the urchins, the kelp (freed from urchins) rebounded, and that recovery restored habitat for fish and other species—a chain of effects set off by restoring the otters. (B) is wrong because the otters ate urchins; they did not plant the kelp. (C) is wrong because urchin numbers fell once the otters preyed on them, not grew. (D) is wrong because the kelp rebounded after the otters arrived, rather than declining." },
];

// ─────────────────────── PRACTICE TEST 22 · R&W M2 easy (27) ─────────────────
const T22_RW_M2E: SatQuestion[] = [
  { id: "t22rw2e-1", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The pillow was so ______ that I fell asleep the moment my head touched it.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["soft", "hard", "loud", "cold"], correct: 0, explanation: "The answer is (A) soft. Falling asleep the moment your head touches the pillow means the pillow was comfortable, which a \"soft\" pillow is. (B) hard would be uncomfortable and would not invite sleep. (C) loud does not describe a pillow at all and has nothing to do with comfort. (D) cold would be unpleasant rather than sleep-inducing." },
  { id: "t22rw2e-2", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The three puppies ______ playing in the backyard.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "The answer is (B) are. The subject \"three puppies\" is plural, so subject-verb agreement requires the plural present-tense verb \"are.\" (A) is is singular and would agree only with a singular subject. (C) was is singular and past tense, wrong in both number and time for the present action. (D) am is the first-person singular form, used only with \"I,\" not with \"puppies.\"" },
  { id: "t22rw2e-3", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Sunflowers can grow taller than a person, with some reaching more than ten feet in a single summer.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Sunflowers can grow very tall in one season.", "Sunflowers never grow taller than a few inches.", "Sunflowers cannot grow in summer.", "Sunflowers are the shortest plants."], correct: 0, explanation: "The answer is (A). The text says sunflowers can grow taller than a person, with some reaching more than ten feet in a single summer, so they can grow very tall in one season. (B) is wrong because growing over ten feet contradicts \"a few inches.\" (C) is wrong because the text says they grow in a single summer. (D) is wrong because plants that reach ten feet are not the shortest plants." },
  { id: "t22rw2e-4", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The forecast warned of heavy rain. ______, we packed our umbrellas before leaving.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "So", "However", "Meanwhile"], correct: 1, explanation: "The answer is (B) So. The rain warning is the cause and packing umbrellas is the effect, so a result transition fits. (A) For example would introduce an instance of a general point, which packing umbrellas is not. (C) However signals contrast, but packing umbrellas agrees with the warning. (D) Meanwhile signals simultaneous events, but the second action results from the first rather than merely occurring alongside it." },
  { id: "t22rw2e-5", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Last night we ______ dinner at our grandmother's house.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["eat", "eats", "ate", "eating"], correct: 2, explanation: "The answer is (C) ate. The time marker \"Last night\" places the action in the past, so the simple past tense \"ate\" is required. (A) eat is present tense and does not match the past time. (B) eats is present-tense singular, wrong in both tense and (with \"we\") number. (D) eating is a non-finite participle that cannot stand alone as the main verb here." },
  { id: "t22rw2e-6", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The morning was so ______ that we could barely see the houses across the street.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["foggy", "sunny", "quiet", "warm"], correct: 0, explanation: "The answer is (A) foggy. Barely being able to see houses across the street means visibility is blocked, which fog does. (B) sunny describes bright, clear weather, which would improve visibility, not reduce it. (C) quiet refers to sound, not sight, so it cannot explain poor visibility. (D) warm describes temperature and has nothing to do with seeing across the street." },
  { id: "t22rw2e-7", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Riding a bicycle saves money on gas, gives good exercise, and produces no pollution.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Cycling offers several benefits.", "Cycling is harmful to health.", "Cycling only saves money.", "Cycling pollutes the air."], correct: 0, explanation: "The answer is (A). The text lists three advantages of cycling—saving money on gas, giving good exercise, and producing no pollution—so cycling offers several benefits. (B) is wrong because the listed effects are positive, not harmful to health. (C) is wrong because saving money is only one of the three benefits, so \"only\" understates them. (D) is wrong because the text says cycling produces no pollution, the opposite of polluting the air." },
  { id: "t22rw2e-8", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "We waited nearly ______ hour for the train to arrive.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "The answer is (B) an. The article before a word is chosen by sound, and \"hour\" begins with a silent h, so it starts with a vowel sound and takes \"an.\" (A) a is used before consonant sounds, but \"hour\" sounds vowel-initial. (C) the only changes the meaning and does not fit \"waited nearly ___ hour.\" (D) some is a quantifier that does not fit the singular \"hour\" in this idiom." },
  { id: "t22rw2e-9", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The joke was so ______ that everyone in the room started laughing.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["funny", "sad", "boring", "serious"], correct: 0, explanation: "The answer is (A) funny. Everyone laughing is the natural result of a \"funny\" joke. (B) sad would prompt sorrow, not laughter. (C) boring would prompt indifference rather than laughter. (D) serious describes a solemn tone, which does not make a room start laughing." },
  { id: "t22rw2e-10", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "My cousin and I ______ visiting the science museum tomorrow.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "The answer is (B) are. The compound subject \"my cousin and I\" is plural, so the plural verb \"are\" agrees. (A) is is singular and does not agree with a two-part subject. (C) was is singular and past tense, wrong in number and in the future \"tomorrow\" context. (D) am is first-person singular, used only with \"I\" alone, not with a compound subject." },
  { id: "t22rw2e-11", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Owls can turn their heads almost all the way around, which helps them watch for prey without moving their bodies.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["An owl's flexible neck helps it watch for prey.", "Owls cannot move their heads at all.", "Owls hunt only during the day.", "Owls have no eyes."], correct: 0, explanation: "The answer is (A). The text says owls can turn their heads almost all the way around, which helps them watch for prey without moving their bodies, so a flexible neck aids hunting. (B) is wrong because turning the head almost all the way around shows owls can move their heads. (C) is wrong because the text does not say owls hunt only during the day. (D) is wrong because watching for prey requires eyes, contradicting the claim that owls have none." },
  { id: "t22rw2e-12", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The power went out during the storm. ______, the city sent crews to restore it.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "As a result", "For example", "Instead"], correct: 1, explanation: "The answer is (B) As a result. The power outage is the cause and the city sending crews is the effect, so a result transition fits. (A) However signals contrast, but sending crews agrees with the need created by the outage. (C) For example would introduce an instance, which sending crews is not. (D) Instead signals substitution of one thing for another, which does not apply." },
  { id: "t22rw2e-13", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Yesterday the baker ______ a dozen loaves of bread.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["bake", "bakes", "baked", "baking"], correct: 2, explanation: "The answer is (C) baked. The time marker \"Yesterday\" places the action in the past, so the simple past \"baked\" is required. (A) bake is present tense and does not match the past time. (B) bakes is present-tense singular, wrong in tense. (D) baking is a participle that cannot stand alone as the main verb here." },
  { id: "t22rw2e-14", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "After hiking all day, the campers were ______ and went straight to sleep.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["tired", "excited", "hungry", "curious"], correct: 0, explanation: "The answer is (A) tired. Hiking all day and then going straight to sleep shows the campers were \"tired.\" (B) excited would keep them awake, not send them to sleep. (C) hungry would lead them to eat, not sleep immediately. (D) curious describes interest in something and does not explain falling asleep at once." },
  { id: "t22rw2e-15", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "The pool is open from 8 a.m. to 8 p.m. on weekdays but is closed for cleaning every Monday.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["You cannot swim at the pool on Monday.", "The pool opens at midnight.", "The pool is open every day.", "The pool closes at 8 a.m."], correct: 0, explanation: "The answer is (A). The text says the pool is closed for cleaning every Monday, so you cannot swim there on Monday. (B) is wrong because the pool opens at 8 a.m., not midnight. (C) is wrong because it is closed Mondays, so it is not open every day. (D) is wrong because 8 a.m. is the opening time, not the closing time (it closes at 8 p.m.)." },
  { id: "t22rw2e-16", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The cat licked ______ paws after eating.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["its", "it's", "their", "they're"], correct: 0, explanation: "The answer is (A) its. The singular possessive \"its\" correctly shows the paws belong to the singular \"cat.\" (B) it's is the contraction of \"it is,\" which makes no sense (\"the cat licked it is paws\"). (C) their is plural and does not agree with the singular \"cat.\" (D) they're is the contraction of \"they are,\" both plural and not a possessive." },
  { id: "t22rw2e-17", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "Some animals hibernate through the winter. ______, bears sleep in their dens for months.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "However", "Instead", "Otherwise"], correct: 0, explanation: "The answer is (A) For example. The first sentence makes a general claim (some animals hibernate), and the second gives bears as an instance of it, so an illustration transition fits. (B) However signals contrast, but bears agree with the general claim. (C) Instead signals substitution of one thing for another, which does not apply. (D) Otherwise introduces an alternative or consequence, not an example." },
  { id: "t22rw2e-18", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The path was very ______, so we had to step carefully over the loose stones.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["rocky", "smooth", "wet", "wide"], correct: 0, explanation: "The answer is (A) rocky. Having to step carefully over loose stones describes a \"rocky\" path. (B) smooth is the opposite of a stone-strewn surface. (C) wet describes moisture, not the stones underfoot. (D) wide describes width and does not explain stepping over stones." },
  { id: "t22rw2e-19", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The shelves ______ filled with old books and dusty maps.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "The answer is (B) are. The subject \"shelves\" is plural, so subject-verb agreement requires the plural \"are.\" (A) is is singular and agrees only with a singular subject. (C) was is singular and past tense, wrong in number for the plural subject. (D) am is first-person singular, used only with \"I.\"" },
  { id: "t22rw2e-20", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Salt was once so valuable that it was used as money; the word 'salary' comes from payments made in salt.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Salt was once valuable enough to be used as money.", "Salt has never had any value.", "Salt cannot be used in cooking.", "Salt is a modern invention."], correct: 0, explanation: "The answer is (A). The text says salt was once so valuable that it was used as money and that \"salary\" derives from payments in salt, so salt was once valuable enough to serve as money. (B) is wrong because being used as money shows salt had great value. (C) is wrong because nothing in the text says salt cannot be used in cooking. (D) is wrong because the text describes salt's ancient use, so it is not a modern invention." },
  { id: "t22rw2e-21", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "We planned to arrive early. ______, a flat tire delayed us by an hour.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "Therefore", "For example", "Similarly"], correct: 0, explanation: "The answer is (A) However. Planning to arrive early but being delayed by a flat tire is a contrast between intention and outcome, which \"However\" signals. (B) Therefore would mark a result, but the delay opposes the plan rather than following from it. (C) For example would introduce an instance, which the flat tire is not. (D) Similarly signals likeness, but the delay is unlike the plan to be early." },
  { id: "t22rw2e-22", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Next month our class ______ to tour the historic capitol building.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["plan", "plans", "planned", "planning"], correct: 1, explanation: "The answer is (B) plans. The singular collective noun \"class\" takes the singular present-tense \"plans,\" and the present-as-future use fits the marker \"next month.\" (A) plan is the plural/base form and disagrees with the singular \"class.\" (C) planned is past tense, which clashes with the future \"next month.\" (D) planning is a participle that cannot serve as the sentence's main verb." },
  { id: "t22rw2e-23", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The river was very ______; we could see the smooth stones on the bottom.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["clear", "muddy", "loud", "deep"], correct: 0, explanation: "The answer is (A) clear. Being able to see the smooth stones on the bottom means the water was \"clear.\" (B) muddy water is cloudy and would hide the stones. (C) loud refers to sound, not to seeing through water. (D) deep water would make the bottom harder to see, not easier." },
  { id: "t22rw2e-24", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Drinking enough water helps the body stay cool, keeps the skin healthy, and aids digestion.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Drinking water benefits the body in several ways.", "Drinking water harms the body.", "Water only cools the body.", "The body needs no water."], correct: 0, explanation: "The answer is (A). The text lists three benefits of drinking water—staying cool, healthy skin, and aiding digestion—so water helps the body in several ways. (B) is wrong because the listed effects are helpful, not harmful. (C) is wrong because cooling is only one of the three benefits, so \"only\" understates them. (D) is wrong because the listed benefits show the body does need water." },
  { id: "t22rw2e-25", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "He grabbed ______ apple from the bowl on his way out.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "The answer is (B) an. \"Apple\" begins with a vowel sound, so the indefinite article \"an\" is correct. (A) a is used before consonant sounds, not the vowel sound of \"apple.\" (C) the only changes the meaning and does not fit \"grabbed ___ apple.\" (D) some is a plural/mass quantifier that does not fit the singular \"apple.\"" },
  { id: "t22rw2e-26", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The directions were easy to follow. ______, the whole project took less than an hour.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["In addition", "However", "Instead", "Otherwise"], correct: 0, explanation: "The answer is (A) In addition. The first sentence says the directions were easy, and the second adds another positive point (the project was quick), so an additive transition fits. (B) However signals contrast, but the two ideas agree. (C) Instead signals substitution, which does not apply. (D) Otherwise introduces an alternative or consequence of not doing something, not an added point." },
  { id: "t22rw2e-27", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The audience was ______ when the band returned for an encore.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["delighted", "annoyed", "silent", "sleepy"], correct: 0, explanation: "The answer is (A) delighted. A band returning for an encore pleases fans, so the audience was \"delighted.\" (B) annoyed describes irritation, the opposite of pleasure at an encore. (C) silent does not fit a crowd reacting to a returning band. (D) sleepy describes drowsiness, which does not match an enthusiastic encore moment." },
];

// ─────────────────────── PRACTICE TEST 22 · R&W M2 hard (27) ─────────────────
const T22_RW_M2H: SatQuestion[] = [
  { id: "t22rw2h-1", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The minister's statement was so ______ that supporters and opponents alike claimed it as an endorsement of their own position.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["ambiguous", "candid", "blunt", "decisive"], correct: 0, explanation: "The answer is (A) ambiguous. A statement that both supporters and opponents can claim as an endorsement must be open to opposite readings, which \"ambiguous\" means. (B) candid means frank and open, implying clarity that would not allow rival claims. (C) blunt means direct and plainspoken, again the kind of clarity that prevents conflicting interpretations. (D) decisive means clear-cut and conclusive, which would settle the meaning rather than leave it claimable by both sides." },
  { id: "t22rw2h-2", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The article first walks through three failed attempts to map the cave system, then uses their shared error—ignoring seasonal flooding—to propose a new surveying method.", prompt: "Which choice best describes the structure of the text?", type: "mcq", choices: ["It examines past failures to derive a general principle for a new approach.", "It presents a method and then abandons it.", "It lists definitions without examples.", "It repeats a single attempt throughout."], correct: 0, explanation: "The answer is (A). The text first walks through three failed mapping attempts, then identifies their shared error (ignoring seasonal flooding) and uses it to propose a new surveying method—examining past failures to derive a general principle for a new approach. (B) is wrong because the text builds toward a method rather than presenting then abandoning one. (C) is wrong because the text gives concrete cases, not bare definitions. (D) is wrong because three distinct attempts are discussed, not a single one repeated." },
  { id: "t22rw2h-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A solar panel produced 95% of its rated output in its first year, 93% in its fifth year, and 78% in its twentieth year.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Output declined more steeply between years five and twenty than before.", "Output rose over time.", "Output stayed exactly constant.", "The panel produced nothing after five years."], correct: 0, explanation: "The answer is (A). Output fell from 95% to 93% over four years (years one to five), a 2-point drop, then from 93% to 78% over the next fifteen years, a 15-point drop, so the decline was far steeper in the later period. (B) is wrong because output fell, not rose. (C) is wrong because the figures change (95, 93, 78), so output did not stay constant. (D) is wrong because the panel still produced 93% in year five and 78% in year twenty, not nothing." },
  { id: "t22rw2h-4", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The new subway line would cut downtown travel times in half. ______, its construction would displace several long-standing neighborhood businesses.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "However", "Likewise", "Accordingly"], correct: 1, explanation: "The answer is (B) However. The first sentence states a benefit (halved travel times) and the second a cost (displaced businesses), so a contrast transition is needed. (A) Therefore signals a result, but the displacement does not follow from the time savings. (C) Likewise signals similarity, but a benefit and a cost are unlike. (D) Accordingly signals consequence, which the opposing ideas do not support." },
  { id: "t22rw2h-5", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The internship teaches students to analyze data, to write reports, and ______ findings to clients.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["to present", "presenting", "present", "presented"], correct: 0, explanation: "The answer is (A) to present. The series \"to analyze data, to write reports, and ___ findings\" uses parallel infinitives, so the third item must also be an infinitive, \"to present.\" (B) presenting is a gerund/participle that breaks the infinitive pattern. (C) present is a bare verb that does not match the \"to + verb\" structure of the other items. (D) presented is a past participle that breaks the parallel series." },
  { id: "t22rw2h-6", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The history refuses to ______ its subjects, depicting the revolutionaries' cruelties as plainly as their ideals.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["romanticize", "condemn", "describe", "recall"], correct: 0, explanation: "The answer is (A) romanticize. Depicting the revolutionaries' cruelties as plainly as their ideals means the history refuses to idealize them, which is what \"romanticize\" means. (B) condemn is the opposite stance; refusing to condemn would not explain showing cruelties plainly. (C) describe is too neutral, since \"refuses to describe\" would contradict the book depicting cruelties at all. (D) recall is likewise too neutral and does not capture the idealizing the book avoids." },
  { id: "t22rw2h-7", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Where earlier economists treated unemployment as a temporary mismatch soon corrected by the market, the newer model regards it as a condition the market can sustain indefinitely without intervention.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To contrast an older view of unemployment with a newer one.", "To prove unemployment never occurs.", "To summarize only the older view.", "To argue that economics is unscientific."], correct: 0, explanation: "The answer is (A). The \"Where earlier economists treated… the newer model regards…\" structure sets an older view of unemployment (a temporary, self-correcting mismatch) against a newer one (a condition the market sustains indefinitely), so the purpose is to contrast the two views. (B) is wrong because the text discusses how unemployment is explained, not that it never occurs. (C) is wrong because it presents both views, not only the older one. (D) is wrong because the text contrasts economic models rather than arguing economics is unscientific." },
  { id: "t22rw2h-8", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The day shift met the production target with ease ______ the night shift fell short of the same goal.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["ease, the", "ease; the", "ease the", "ease: the"], correct: 1, explanation: "Two independent clauses are correctly joined by a semicolon. A comma alone would splice them, and a colon does not fit two contrasting clauses." },
  { id: "t22rw2h-9", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Far from being ______, the treaty's language was riddled with loopholes that each nation interpreted to its own advantage.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["airtight", "vague", "flexible", "contested"], correct: 0, explanation: "\"Far from\" signals an opposite, and language full of loopholes is the opposite of \"airtight.\" \"Vague\" and \"contested\" describe what the language actually was, not its opposite." },
  { id: "t22rw2h-10", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Supporters insist the new curriculum raised test scores without increasing teacher workload. Yet surveys show teachers now spend an extra six hours a week on lesson planning.", prompt: "Which choice best describes the function of the second sentence?", type: "mcq", choices: ["It offers evidence that complicates the supporters' claim.", "It restates the supporters' claim word for word.", "It confirms that workload did not change.", "It proposes a new curriculum."], correct: 0, explanation: "The answer is (A). Supporters claim the curriculum raised scores \"without increasing teacher workload,\" and the second sentence's survey finding of six extra hours of weekly planning is evidence that complicates that claim. (B) is wrong because the second sentence introduces new survey data, not a restatement of the claim. (C) is wrong because six extra hours indicates workload did change. (D) is wrong because the sentence reports survey results, not a proposal for a new curriculum." },
  { id: "t22rw2h-11", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The voyage required three essential items ______ a reliable compass, a detailed chart, and a seaworthy vessel.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["items,", "items:", "items;", "items"], correct: 1, explanation: "A colon introduces the list that specifies the \"three essential items.\" A comma is insufficient and a semicolon needs an independent clause after it." },
  { id: "t22rw2h-12", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The algorithm sorted the photographs with near-perfect accuracy. ______, it could not explain which features had guided any single decision.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Indeed", "Nonetheless", "Therefore", "Likewise"], correct: 1, explanation: "A success paired with a notable limitation is a concession, best signaled by \"Nonetheless.\" \"Indeed,\" \"Therefore,\" and \"Likewise\" do not capture the contrast." },
  { id: "t22rw2h-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "In a controlled study, students who used the new tutoring app scored 15% higher on the final exam but reported spending 25% more time studying than the control group.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The app users scored higher but also studied more.", "The app users scored higher while studying less.", "The app had no effect on scores.", "The control group studied more than the app users."], correct: 0, explanation: "The answer is (A). The study reports app users scored 15% higher AND spent 25% more time studying, so both their score and their study time rose. (B) is wrong because they studied more, not less. (C) is wrong because the 15% higher score shows the app was associated with an effect on scores. (D) is wrong because the app users studied 25% more, so the control group did not study more." },
  { id: "t22rw2h-14", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The fresco that decorates the chapel's ceiling ______ to the artist's final decade, long after his celebrated early portraits.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["belong", "belongs", "belonging", "to belong"], correct: 1, explanation: "The answer is (B) belongs. The true subject is the singular \"fresco\"; the intervening words \"that decorates the chapel's ceiling\" and the later \"portraits\" do not control the verb, so the singular \"belongs\" is required. (A) belong is the plural form and disagrees with the singular subject. (C) belonging is a participle that cannot serve as the main verb here. (D) to belong is an infinitive that cannot serve as the main verb." },
  { id: "t22rw2h-15", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The editor was admired for her ______ — for cutting any sentence that did not advance the argument, however elegant it might be.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["rigor", "leniency", "indecision", "nostalgia"], correct: 0, explanation: "Cutting every nonessential sentence reflects strict discipline, or \"rigor.\" \"Leniency\" and \"indecision\" describe the opposite tendency." },
  { id: "t22rw2h-16", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author opens by admitting that early electric cars were slow and short-ranged, then argues that these very shortcomings concentrated engineering effort on the battery advances that now make the cars practical.", prompt: "Which choice best describes the text's reasoning?", type: "mcq", choices: ["It recasts an apparent weakness as the source of later strengths.", "It denies that early electric cars had any flaws.", "It claims the cars never improved.", "It lists car prices over time."], correct: 0, explanation: "The answer is (A). The author admits early electric cars were slow and short-ranged, then argues those very shortcomings concentrated effort on the battery advances that now make the cars practical—recasting an apparent weakness as the source of later strengths. (B) is wrong because the author admits the cars had flaws. (C) is wrong because the author says the cars later became practical, so they did improve. (D) is wrong because the text discusses engineering, not a list of car prices." },
  { id: "t22rw2h-17", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "Having studied the score for weeks ______ the conductor led the orchestra without once glancing at the page.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["the orchestra played without glancing at the page", "the conductor led the orchestra without glancing at the page", "without glancing, the page was unnecessary", "it was led without the page, the orchestra"], correct: 1, explanation: "The answer is (B). The introductory phrase \"Having studied the score for weeks\" must modify the noun that follows it, and only the conductor could have studied the score, so \"the conductor\" must come next. (A) is wrong because it makes \"the orchestra\" the one that studied the score, which is illogical. (C) is wrong because it makes \"the page\" the studier and garbles the sentence. (D) is wrong because it makes \"it\"/\"the orchestra\" the subject of the studying and is incoherent." },
  { id: "t22rw2h-18", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The vaccine produced a strong immune response in the laboratory. ______, results in early human trials were far weaker, and larger trials remain to be done.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Consequently", "In human trials, however", "For this reason", "Similarly"], correct: 1, explanation: "The answer is (B) In human trials, however. The lab showed a strong response but human trials were far weaker, so a contrast transition is needed, and \"however\" supplies it while naming the setting. (A) Consequently signals a result, but the weaker human result does not follow from the strong lab result. (C) For this reason also signals consequence, which the contrast does not support. (D) Similarly signals likeness, but the human results were unlike the lab results." },
  { id: "t22rw2h-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The critic praised the symphony's ______ design, noting how a brief opening motif returns, reshaped, in each of its four movements.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["cohesive", "fragmented", "arbitrary", "monotonous"], correct: 0, explanation: "A motif that recurs across all movements ties the work together, making the design \"cohesive.\" \"Fragmented\" and \"arbitrary\" describe the opposite, and \"monotonous\" misreads recurrence as dullness." },
  { id: "t22rw2h-20", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Across six districts, schools that adopted later start times saw attendance rise by an average of 9%, while schools that kept earlier start times saw no measurable change.", prompt: "Which claim is best supported by the data?", type: "mcq", choices: ["Later start times were associated with higher attendance.", "Earlier start times raised attendance.", "Start times had no relationship to attendance.", "All schools adopted later start times."], correct: 0, explanation: "The answer is (A). Schools that adopted later start times saw attendance rise 9% on average, while those keeping earlier starts saw no measurable change, so later starts were associated with higher attendance. (B) is wrong because earlier-start schools saw no change, so earlier starts did not raise attendance. (C) is wrong because the 9% difference shows a relationship between start time and attendance. (D) is wrong because some schools kept earlier start times, so not all adopted later ones." },
  { id: "t22rw2h-21", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The composer's earliest works — brief, bold, and faintly experimental ______ already hinted at the sound her mature symphonies would perfect.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["works —", "works,", "works", "works;"], correct: 0, explanation: "A pair of dashes sets off the interrupting description, so the second dash must close it. A comma or semicolon cannot pair with the opening dash." },
  { id: "t22rw2h-22", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Officials dismissed the inspector's report as ______, only to see the very bridge it flagged close for emergency repairs months later.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["overcautious", "prophetic", "accurate", "urgent"], correct: 0, explanation: "Dismissing a warning that later proves correct means they wrongly judged it \"overcautious.\" \"Prophetic\" and \"accurate\" would describe the report's actual value, not the officials' mistaken view." },
  { id: "t22rw2h-23", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "One historian attributes the empire's collapse to overextended supply lines; a second blames a sequence of harsh winters. A third contends that the two factors compounded one another.", prompt: "Which choice best describes the third historian's position?", type: "mcq", choices: ["The two proposed factors worked together to cause the collapse.", "Neither supply lines nor winters played any role.", "Only the supply lines mattered.", "The empire never actually collapsed."], correct: 0, explanation: "The answer is (A). The third historian contends the two proposed factors—overextended supply lines and harsh winters—\"compounded one another,\" meaning they worked together to cause the collapse. (B) is wrong because the third historian credits both factors, not neither. (C) is wrong because the third historian does not single out supply lines alone. (D) is wrong because the third historian accepts that the collapse occurred." },
  { id: "t22rw2h-24", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The technicians recalibrated the sensor ______ the original readings had drifted steadily over the course of the experiment.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["sensor, the", "sensor; the", "sensor the", "sensor: the"], correct: 1, explanation: "Two independent clauses are correctly joined by a semicolon. A comma alone splices them, and a colon does not fit these two clauses." },
  { id: "t22rw2h-25", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The author wants to stress that the program's gains were narrowly distributed. ______, urban hospitals received new equipment while rural clinics saw almost no funding.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Specifically", "In contrast", "Nevertheless", "Otherwise"], correct: 0, explanation: "The answer is (A) Specifically. The first sentence makes a general point (gains were narrowly distributed), and the second gives a concrete example of it (urban hospitals got equipment while rural clinics got almost nothing), so an illustration transition fits. (B) In contrast signals opposition, but the example supports the general point. (C) Nevertheless signals concession, which the example does not introduce. (D) Otherwise introduces an alternative, not an illustration." },
  { id: "t22rw2h-26", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Rather than tying every thread together, the screenwriter leaves the protagonist's fate ______, inviting viewers to imagine what becomes of her.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["unresolved", "settled", "trivial", "obvious"], correct: 0, explanation: "Declining to tie threads together leaves the fate \"unresolved.\" \"Settled\" and \"obvious\" contradict the open invitation to imagine an outcome." },
  { id: "t22rw2h-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author concedes that her dataset covers only a single decade, but she argues that the trend it reveals is so steep and uninterrupted that it warrants a broader historical study.", prompt: "Which choice best describes the author's reasoning?", type: "mcq", choices: ["She acknowledges a limitation while defending the finding's significance.", "She claims her dataset is flawless.", "She abandons her finding entirely.", "She argues no further study is needed."], correct: 0, explanation: "The answer is (A). The author concedes a limitation (the dataset covers only one decade) but defends the finding by arguing the trend is so steep and uninterrupted that it warrants a broader study—acknowledging a weakness while defending the finding's significance. (B) is wrong because she admits the dataset's narrow span, so she does not call it flawless. (C) is wrong because she defends rather than abandons the finding. (D) is wrong because she explicitly calls for further historical study." },
];

