const T22_M_M1: SatQuestion[] = [
  { id: "t22m1-1", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5x + 7 = 42, what is the value of x?", type: "grid", gridAnswers: ["7"], explanation: "Goal: solve for x. Subtract 7 from both sides: 5x = 35. Divide by 5: x = 7. Check: 5(7) + 7 = 35 + 7 = 42. A common trap is dividing before subtracting, which gives the wrong value." },
  { id: "t22m1-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A recipe uses 2 cups of rice to serve 6 people. How many cups are needed to serve 15 people?", type: "mcq", choices: ["5", "4", "6", "7"], correct: 0, explanation: "Goal: scale the rice with the servings. The rate is 2/6 = 1/3 cup per person. For 15 people: (1/3)(15) = 5 cups. Check: 5 cups ÷ (1/3 cup per person) = 15 people. The trap is multiplying 2 by 15 without dividing by 6." },
  { id: "t22m1-3", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = 3x² − 4, what is the value of f(2)?", type: "mcq", choices: ["8", "2", "20", "5"], correct: 0, explanation: "Goal: evaluate f at x = 2. Substitute: f(2) = 3(2²) − 4 = 3(4) − 4. Compute: 12 − 4 = 8. The trap is squaring after multiplying by 3, i.e. (3·2)² = 36, which ignores order of operations." },
  { id: "t22m1-4", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a diameter of 18. What is its radius?", type: "grid", gridAnswers: ["9"], explanation: "Goal: find the radius from the diameter. The radius is half the diameter: r = 18 ÷ 2 = 9. Check: doubling 9 gives the diameter 18. The trap is confusing radius with diameter and answering 18 or 36." },
  { id: "t22m1-5", section: "math", domain: "Algebra", difficulty: "med", prompt: "The line y = 3x − 5 passes through the point (4, k). What is the value of k?", type: "grid", gridAnswers: ["7"], explanation: "Goal: find the y-value when x = 4. Substitute x = 4: k = 3(4) − 5. Compute: 12 − 5 = 7. Check: the point (4, 7) lies on the line. The trap is plugging 4 in for y instead of x." },
  { id: "t22m1-6", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "The mean of the numbers 6, 10, and x is 9. What is the value of x?", type: "mcq", choices: ["11", "9", "8", "13"], correct: 0, explanation: "Goal: find x given the mean. Set up (6 + 10 + x)/3 = 9, so 16 + x = 27. Solve: x = 11. Check: (6 + 10 + 11)/3 = 27/3 = 9. The trap is forgetting to multiply the mean by 3." },
  { id: "t22m1-7", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 3x + 8 = 29, what is the value of x?", type: "mcq", choices: ["7", "21", "9", "11"], correct: 0, explanation: "Goal: solve for x. Subtract 8: 3x = 21. Divide by 3: x = 7. Check: 3(7) + 8 = 21 + 8 = 29. The trap of choice B is stopping at 3x = 21 instead of dividing." },
  { id: "t22m1-8", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "What is the sum of the solutions to x² − 9x + 20 = 0?", type: "grid", gridAnswers: ["9"], explanation: "Goal: sum the roots. Factor: (x − 4)(x − 5) = 0, giving roots 4 and 5. Their sum is 9, which also equals −b/a = 9/1. Check: 4 + 5 = 9. The trap is summing to the product 20 instead." },
  { id: "t22m1-9", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A book's price rose from $40 to $46. What was the percent increase?", type: "mcq", choices: ["15%", "6%", "12%", "20%"], correct: 0, explanation: "Goal: find the percent increase. The increase is 46 − 40 = 6. Divide by the original: 6/40 = 0.15 = 15%. Check: 40 × 1.15 = 46. The trap is using 6/46 instead of 6/40." },
  { id: "t22m1-10", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "Two angles of a triangle measure 35° and 85°. What is the measure, in degrees, of the third angle?", type: "grid", gridAnswers: ["60"], explanation: "Goal: find the missing angle. The angles of a triangle sum to 180°: 180 − 35 − 85 = 60°. Check: 35 + 85 + 60 = 180. The trap is using 360° instead of 180°." },
  { id: "t22m1-11", section: "math", domain: "Algebra", difficulty: "med", prompt: "A plumber charges a $40 service fee plus $30 per hour. Which equation gives the cost C for h hours?", type: "mcq", choices: ["C = 30h + 40", "C = 40h + 30", "C = 70h", "C = 30h − 40"], correct: 0, explanation: "Goal: model the cost. The fixed fee is 40 and the hourly rate is 30 per hour, so C = 30h + 40. Check: for h = 2, C = 60 + 40 = 100. The trap is swapping the fee and the rate, as in choice B." },
  { id: "t22m1-12", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If (x + 5)(x − 2) = x² + bx − 10, what is the value of b?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find b after expanding. (x + 5)(x − 2) = x² − 2x + 5x − 10 = x² + 3x − 10, so b = 3. Check: the middle terms −2x and +5x combine to 3x. The trap is forgetting to combine like terms." },
  { id: "t22m1-13", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "In a survey of 250 people, 40% preferred coffee. How many people preferred coffee?", type: "mcq", choices: ["100", "90", "40", "150"], correct: 0, explanation: "Goal: find 40% of 250. Multiply: 0.40 × 250 = 100. Check: 100 is 40% of 250 since 250 × 0.4 = 100. The trap is answering 150, which is the number who did not prefer coffee." },
  { id: "t22m1-14", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5(x − 3) = 2x + 9, what is the value of x?", type: "mcq", choices: ["8", "6", "4", "12"], correct: 0, explanation: "Goal: solve for x. Expand: 5x − 15 = 2x + 9. Subtract 2x and add 15: 3x = 24. Divide: x = 8. Check: 5(8 − 3) = 25 and 2(8) + 9 = 25. The trap is mishandling the distribution of 5." },
  { id: "t22m1-15", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A rectangle has length 12 and width 5. What is its perimeter?", type: "mcq", choices: ["34", "60", "17", "24"], correct: 0, explanation: "Goal: find the perimeter. Use P = 2(l + w) = 2(12 + 5) = 2(17) = 34. Check: 12 + 5 + 12 + 5 = 34. The trap is computing the area, 12 × 5 = 60, instead of the perimeter." },
  { id: "t22m1-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 3^(x−1) = 27, what is the value of x?", type: "grid", gridAnswers: ["4"], explanation: "Goal: solve the exponential equation. Write 27 as 3³, so 3^(x−1) = 3³, meaning x − 1 = 3. Solve: x = 4. Check: 3^(4−1) = 3³ = 27. The trap is treating 27 as 3^27 or mishandling the exponent." },
  { id: "t22m1-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A map uses a scale of 1 inch = 30 miles. Two towns are 5 inches apart on the map. How many miles apart are they?", type: "mcq", choices: ["150", "120", "90", "180"], correct: 0, explanation: "Goal: convert map distance to miles. Multiply: 5 × 30 = 150 miles. Check: 150 miles ÷ 30 miles per inch = 5 inches. The trap is dividing instead of multiplying by the scale." },
  { id: "t22m1-18", section: "math", domain: "Algebra", difficulty: "med", prompt: "The slope of the line through (2, 3) and (6, 15) is what value?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find the slope. Use (y₂ − y₁)/(x₂ − x₁) = (15 − 3)/(6 − 2) = 12/4 = 3. Check: rising 12 over a run of 4 gives a slope of 3. The trap is inverting the formula to 4/12." },
  { id: "t22m1-19", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = 4x + 5, what value of x makes f(x) = 25?", type: "mcq", choices: ["5", "7", "6", "4"], correct: 0, explanation: "Goal: solve f(x) = 25. Set 4x + 5 = 25, so 4x = 20 and x = 5. Check: f(5) = 4(5) + 5 = 25. The trap is dividing 25 by 4 before subtracting 5." },
  { id: "t22m1-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a radius of 7. What is its area, in terms of π?", type: "mcq", choices: ["49π", "14π", "7π", "21π"], correct: 0, explanation: "Goal: find the area. Use A = πr² = π(7²) = 49π. Check: 7² = 49, so the area is 49π. The trap is computing the circumference 2πr = 14π instead of the area." },
  { id: "t22m1-21", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 4x − y = 17 and y = 3, what is the value of x?", type: "mcq", choices: ["5", "4", "6", "7"], correct: 0, explanation: "Goal: solve for x. Substitute y = 3: 4x − 3 = 17, so 4x = 20 and x = 5. Check: 4(5) − 3 = 17. The trap is adding 3 to the wrong side or forgetting to divide by 4." },
  { id: "t22m1-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A worker earns $22 per hour. How much does the worker earn for a 40-hour week?", type: "grid", gridAnswers: ["880"], explanation: "Goal: find total weekly pay. Multiply the rate by the hours: 22 × 40 = 880 dollars. Check: 22 × 4 = 88, then ×10 = 880. The trap is adding instead of multiplying." },
];

// ─────────────────────── PRACTICE TEST 22 · MATH M2 easy (22) ────────────────
const T22_M_M2E: SatQuestion[] = [
  { id: "t22m2e-1", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x + 9 = 17, what is the value of x?", type: "grid", gridAnswers: ["8"], explanation: "Goal: solve for x. Subtract 9 from both sides: x = 17 − 9 = 8. Check: 8 + 9 = 17. The trap is adding the two numbers to get 26." },
  { id: "t22m2e-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is 20% of 80?", type: "mcq", choices: ["16", "20", "60", "40"], correct: 0, explanation: "Goal: find 20% of 80. Multiply: 0.20 × 80 = 16. Check: 10% of 80 is 8, so 20% is 16. The trap is answering 20, the percent itself." },
  { id: "t22m2e-3", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A rectangle has a length of 9 and a width of 4. What is its area?", type: "grid", gridAnswers: ["36"], explanation: "Goal: find the area. Multiply length by width: 9 × 4 = 36. Check: 9 × 4 counts 36 unit squares. The trap is finding the perimeter, 2(9 + 4) = 26." },
  { id: "t22m2e-4", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 8x = 56, what is the value of x?", type: "mcq", choices: ["7", "8", "48", "64"], correct: 0, explanation: "Goal: solve for x. Divide both sides by 8: x = 56 ÷ 8 = 7. Check: 8 × 7 = 56. The trap is subtracting 8 from 56 to get 48." },
  { id: "t22m2e-5", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "What is the value of 5² − 4?", type: "grid", gridAnswers: ["21"], explanation: "Goal: evaluate the expression. Square first: 5² = 25. Then subtract: 25 − 4 = 21. Check: 25 − 4 = 21. The trap is subtracting before squaring, as in (5 − 4)² = 1." },
  { id: "t22m2e-6", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A team won 8 of its 12 games. What fraction of its games did it win?", type: "mcq", choices: ["2/3", "8/12", "1/2", "3/4"], correct: 0, explanation: "Goal: write the win fraction in simplest form. 8/12 divides by 4 to give 2/3. Check: 2/3 × 12 = 8 wins. Choice B is correct in value but not reduced, so 2/3 is the simplest form." },
  { id: "t22m2e-7", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x − 5 = 11, what is the value of x?", type: "grid", gridAnswers: ["16"], explanation: "Goal: solve for x. Add 5 to both sides: x = 11 + 5 = 16. Check: 16 − 5 = 11. The trap is subtracting to get 6." },
  { id: "t22m2e-8", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is the average of 12, 18, and 30?", type: "mcq", choices: ["20", "30", "15", "60"], correct: 0, explanation: "Goal: find the mean. Add the values: 12 + 18 + 30 = 60. Divide by 3: 60/3 = 20. Check: 20 × 3 = 60. The trap is reporting the sum 60 as the average." },
  { id: "t22m2e-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A square has a side length of 9. What is its perimeter?", type: "grid", gridAnswers: ["36"], explanation: "Goal: find the perimeter. A square has four equal sides: P = 4 × 9 = 36. Check: 9 + 9 + 9 + 9 = 36. The trap is finding the area, 9² = 81." },
  { id: "t22m2e-10", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 2x + 3 = 15, what is the value of x?", type: "mcq", choices: ["6", "9", "12", "5"], correct: 0, explanation: "Goal: solve for x. Subtract 3: 2x = 12. Divide by 2: x = 6. Check: 2(6) + 3 = 15. The trap is stopping at 2x = 12 and answering 12." },
  { id: "t22m2e-11", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "If f(x) = x + 8, what is f(6)?", type: "grid", gridAnswers: ["14"], explanation: "Goal: evaluate f at 6. Substitute: f(6) = 6 + 8 = 14. Check: 6 + 8 = 14. The trap is multiplying 6 by 8 instead of adding." },
  { id: "t22m2e-12", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A store sells 5 notebooks for $10. How much do 8 notebooks cost?", type: "mcq", choices: ["$16", "$15", "$18", "$13"], correct: 0, explanation: "Goal: find the cost of 8 notebooks. Each notebook costs 10/5 = $2, so 8 cost 8 × 2 = $16. Check: $16 ÷ $2 = 8 notebooks. The trap is adding $3 to the $10 base price." },
  { id: "t22m2e-13", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 6x = 48, what is the value of x?", type: "mcq", choices: ["8", "7", "6", "42"], correct: 0, explanation: "Goal: solve for x. Divide both sides by 6: x = 48 ÷ 6 = 8. Check: 6 × 8 = 48. The trap is subtracting 6 from 48 to get 42." },
  { id: "t22m2e-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A triangle has a base of 12 and a height of 5. What is its area?", type: "grid", gridAnswers: ["30"], explanation: "Goal: find the triangle's area. Use A = (1/2)(base)(height) = (1/2)(12)(5) = 30. Check: 12 × 5 = 60, and half of 60 is 30. The trap is forgetting the factor of 1/2 and answering 60." },
  { id: "t22m2e-15", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is 25% of 64?", type: "mcq", choices: ["16", "32", "8", "48"], correct: 0, explanation: "Goal: find 25% of 64. Since 25% is one quarter, divide: 64 ÷ 4 = 16. Check: 16 × 4 = 64. The trap is computing 50% (32) instead of 25%." },
  { id: "t22m2e-16", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x/3 = 7, what is the value of x?", type: "grid", gridAnswers: ["21"], explanation: "Goal: solve for x. Multiply both sides by 3: x = 7 × 3 = 21. Check: 21 ÷ 3 = 7. The trap is dividing 7 by 3 instead of multiplying." },
  { id: "t22m2e-17", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "What is the value of 3³?", type: "mcq", choices: ["27", "9", "12", "81"], correct: 0, explanation: "Goal: evaluate 3³. Multiply: 3 × 3 × 3 = 27. Check: 9 × 3 = 27. The trap is computing 3 × 3 = 9 and stopping early." },
  { id: "t22m2e-18", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A car travels 120 miles in 3 hours. What is its average speed in miles per hour?", type: "mcq", choices: ["40", "60", "360", "30"], correct: 0, explanation: "Goal: find the average speed. Divide distance by time: 120 ÷ 3 = 40 mph. Check: 40 × 3 = 120 miles. The trap is multiplying to get 360 instead of dividing." },
  { id: "t22m2e-19", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 4x − 8 = 12, what is the value of x?", type: "grid", gridAnswers: ["5"], explanation: "Goal: solve for x. Add 8: 4x = 20. Divide by 4: x = 5. Check: 4(5) − 8 = 12. The trap is dividing 12 by 4 before adding 8." },
  { id: "t22m2e-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A circle has a diameter of 16. What is its radius?", type: "mcq", choices: ["8", "16", "32", "4"], correct: 0, explanation: "Goal: find the radius. Divide the diameter by 2: 16 ÷ 2 = 8. Check: 8 × 2 = 16. The trap is doubling the diameter to get 32." },
  { id: "t22m2e-21", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If y = 3x and x = 5, what is the value of y?", type: "mcq", choices: ["15", "8", "2", "12"], correct: 0, explanation: "Goal: find y. Substitute x = 5: y = 3 × 5 = 15. Check: 15 ÷ 3 = 5. The trap is adding 3 and 5 to get 8." },
  { id: "t22m2e-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A bag holds 9 green and 6 yellow marbles. What fraction of the marbles are yellow?", type: "mcq", choices: ["2/5", "6/9", "1/2", "3/5"], correct: 0, explanation: "Goal: find the fraction that is yellow. There are 6 yellow out of 9 + 6 = 15 total, so 6/15 = 2/5. Check: 2/5 × 15 = 6. The trap is writing 6/9 by dividing yellow by green instead of by the total." },
];

// ─────────────────────── PRACTICE TEST 22 · MATH M2 hard (22) ────────────────
const T22_M_M2H: SatQuestion[] = [
  { id: "t22m2h-1", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² − 64 = 0 and x > 0, what is the value of x?", type: "grid", gridAnswers: ["8"], explanation: "Goal: solve for the positive root. Add 64: x² = 64, so x = ±8. Since x > 0, x = 8. Check: 8² − 64 = 0. The trap is reporting −8 or both roots when only the positive one is allowed." },
  { id: "t22m2h-2", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 2x + 3y = 18 and x − 3y = 0, what is the value of x?", type: "mcq", choices: ["6", "9", "3", "12"], correct: 0, explanation: "Goal: solve for x. Add the equations to eliminate y: (2x + 3y) + (x − 3y) = 18 + 0, giving 3x = 18, so x = 6. Check: with x = 6, x − 3y = 0 gives y = 2, and 2(6) + 3(2) = 18. The trap is subtracting the equations and losing the cancellation." },
  { id: "t22m2h-3", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 2^x = 64, what is the value of x?", type: "grid", gridAnswers: ["6"], explanation: "Goal: solve the exponential. Write 64 as a power of 2: 64 = 2⁶, so x = 6. Check: 2⁶ = 64. The trap is dividing 64 by 2 and answering 32." },
  { id: "t22m2h-4", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A coat originally priced at $90 is marked up by 30%. What is the new price?", type: "mcq", choices: ["$117", "$120", "$113", "$63"], correct: 0, explanation: "Goal: find the marked-up price. The markup is 30% of 90 = 0.30 × 90 = 27. Add: 90 + 27 = $117. Check: 90 × 1.30 = 117. The trap is computing a 30% discount, which would give $63." },
  { id: "t22m2h-5", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A right triangle has legs of length 8 and 15. What is the length of the hypotenuse?", type: "grid", gridAnswers: ["17"], explanation: "Goal: find the hypotenuse. Use the Pythagorean theorem: c = √(8² + 15²) = √(64 + 225) = √289 = 17. Check: 8-15-17 is a known Pythagorean triple. The trap is adding the legs to get 23." },
  { id: "t22m2h-6", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If p(x) = 3x − 2, what is the value of p(p(2))?", type: "mcq", choices: ["10", "4", "12", "7"], correct: 0, explanation: "Goal: evaluate the composition. First p(2) = 3(2) − 2 = 4. Then p(4) = 3(4) − 2 = 10. Check: feeding 4 back in gives 12 − 2 = 10. The trap is stopping at p(2) = 4." },
  { id: "t22m2h-7", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 2x + 5y = 19 and x = y + 1, what is the value of y?", type: "grid", gridAnswers: ["17/7", "2.428", "2.429"], explanation: "Goal: find y by substitution. Replace x with y + 1: 2(y + 1) + 5y = 19, so 7y + 2 = 19. Then 7y = 17 and y = 17/7. Check: y = 17/7 ≈ 2.43, x = 24/7, and 2(24/7) + 5(17/7) = 133/7 = 19. The trap is forgetting to distribute the 2 across y + 1." },
  { id: "t22m2h-8", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "The parabola y = x² − 8x + 7 has its vertex at (h, k). What is the value of h?", type: "grid", gridAnswers: ["4"], explanation: "Goal: find the x-coordinate of the vertex. Use h = −b/(2a) = −(−8)/(2·1) = 8/2 = 4. Check: completing the square gives y = (x − 4)² − 9, vertex at x = 4. The trap is using +b instead of −b and answering −4." },
  { id: "t22m2h-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "In a right triangle, the acute angle θ has cos θ = 5/13. What is sin θ?", type: "mcq", choices: ["12/13", "5/12", "13/12", "12/5"], correct: 0, explanation: "Goal: find sin θ. In a 5-12-13 right triangle, the adjacent side is 5 and the hypotenuse 13, so the opposite side is 12 and sin θ = 12/13. Check: (5/13)² + (12/13)² = 25/169 + 144/169 = 1. The trap is dividing the wrong two sides." },
  { id: "t22m2h-10", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² + bx + 25 is a perfect square trinomial and b > 0, what is the value of b?", type: "grid", gridAnswers: ["10"], explanation: "Goal: find b. A perfect square (x + a)² = x² + 2ax + a² needs a² = 25, so a = 5, and b = 2a = 10. Check: (x + 5)² = x² + 10x + 25. The trap is taking b = 25 or b = 5 rather than doubling a." },
  { id: "t22m2h-11", section: "math", domain: "Algebra", difficulty: "hard", prompt: "A line has slope −3 and passes through (2, 5). What is its y-intercept?", type: "mcq", choices: ["11", "−1", "5", "8"], correct: 0, explanation: "Goal: find the y-intercept b. Use y = −3x + b with the point (2, 5): 5 = −3(2) + b, so 5 = −6 + b and b = 11. Check: y = −3x + 11 passes through (2, 5). The trap is adding −6 instead of subtracting it from 5." },
  { id: "t22m2h-12", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "After a 25% discount, a tablet costs $360. What was the original price?", type: "mcq", choices: ["$480", "$450", "$385", "$300"], correct: 0, explanation: "Goal: find the original price. A 25% discount leaves 75%, so 0.75 × original = 360. Divide: original = 360 / 0.75 = $480. Check: 25% of 480 is 120, and 480 − 120 = 360. The trap is adding 25% of 360, which undercounts." },
  { id: "t22m2h-13", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If f(x) = x² and f(a) = 49 with a < 0, what is the value of a?", type: "grid", gridAnswers: ["-7"], explanation: "Goal: find the negative root. Set a² = 49, so a = ±7; since a < 0, a = −7. Check: (−7)² = 49. The trap is reporting the positive root 7 and ignoring the constraint a < 0." },
  { id: "t22m2h-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A cylinder has radius 4 and height 6. What is its volume, in terms of π?", type: "mcq", choices: ["96π", "48π", "24π", "144π"], correct: 0, explanation: "Goal: find the volume. Use V = πr²h = π(4²)(6) = π(16)(6) = 96π. Check: 16 × 6 = 96. The trap is using r instead of r², which gives 24π." },
  { id: "t22m2h-15", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 1/x + 1/4 = 1, what is the value of x?", type: "grid", gridAnswers: ["4/3", "1.333"], explanation: "Goal: solve for x. Subtract 1/4: 1/x = 1 − 1/4 = 3/4. Take the reciprocal: x = 4/3 ≈ 1.33. Check: 1/(4/3) + 1/4 = 3/4 + 1/4 = 1. The trap is forgetting to invert and answering 3/4." },
  { id: "t22m2h-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "What is the product of the solutions to x² − 7x + 10 = 0?", type: "mcq", choices: ["10", "7", "−10", "3"], correct: 0, explanation: "Goal: find the product of the roots. Factor: (x − 2)(x − 5) = 0, roots 2 and 5, product 10, which equals c/a = 10/1. Check: 2 × 5 = 10. The trap is reporting the sum 7 instead of the product." },
  { id: "t22m2h-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "The ratio of red to blue tiles in a box is 2:7. If there are 54 tiles total, how many are blue?", type: "mcq", choices: ["42", "12", "36", "48"], correct: 0, explanation: "Goal: find the number of blue tiles. The ratio has 2 + 7 = 9 parts, so each part is 54/9 = 6 tiles. Blue gets 7 parts: 7 × 6 = 42. Check: red = 12, blue = 42, total 54. The trap is using 2 parts for blue and answering 12." },
  { id: "t22m2h-18", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "Two similar triangles have a scale factor of 1:4. If the smaller has area 3, what is the area of the larger?", type: "grid", gridAnswers: ["48"], explanation: "Goal: scale the area. Areas scale by the square of the linear ratio, so the factor is 4² = 16. Multiply: 3 × 16 = 48. Check: 3 × 16 = 48. The trap is multiplying by 4 instead of 16." },
  { id: "t22m2h-19", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If √(x + 5) = 6, what is the value of x?", type: "grid", gridAnswers: ["31"], explanation: "Goal: solve for x. Square both sides: x + 5 = 36. Subtract 5: x = 31. Check: √(31 + 5) = √36 = 6. The trap is forgetting to square the 6 and using 6 directly." },
  { id: "t22m2h-20", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 5x − 2y = 24 and y = 3, what is the value of x?", type: "mcq", choices: ["6", "5", "4", "8"], correct: 0, explanation: "Goal: solve for x. Substitute y = 3: 5x − 6 = 24, so 5x = 30 and x = 6. Check: 5(6) − 2(3) = 30 − 6 = 24. The trap is subtracting 6 from the wrong side or skipping the division by 5." },
  { id: "t22m2h-21", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If g(x) = x² − 6x + 9, for what value of x does g(x) = 0?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find the root. Factor the perfect square: g(x) = (x − 3)², which equals 0 only when x = 3. Check: 3² − 6(3) + 9 = 9 − 18 + 9 = 0. The trap is expecting two distinct roots for a repeated root." },
  { id: "t22m2h-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A colony of bacteria triples every hour. If it starts at 20, how many are there after 3 hours?", type: "mcq", choices: ["540", "180", "60", "1620"], correct: 0, explanation: "Goal: find the population after 3 hours. Tripling three times multiplies by 3³ = 27, so 20 × 27 = 540. Check: 20 → 60 → 180 → 540. The trap is stopping after one or two hours, giving 60 or 180." },
];

